use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Fix common Cargo.toml feature issues that break compilation"] pub fn fix_cargo_features (cargo_toml_path : & Path) -> Result < () > { let content = std :: fs :: read_to_string (cargo_toml_path) ? ; let mut doc = content . parse :: < toml_edit :: DocumentMut > () ? ; if let Some (features) = doc . get ("features") . and_then (| f | f . as_table ()) { let mut needs_rustc_alloc = false ; let mut needs_rustc_core = false ; let mut needs_rustc_std = false ; for (_ , feature_list) in features . iter () { if let Some (arr) = feature_list . as_array () { for item in arr . iter () { if let Some (s) = item . as_str () { if s == "rustc-std-workspace-alloc" { needs_rustc_alloc = true ; } else if s == "rustc-std-workspace-core" { needs_rustc_core = true ; } else if s == "rustc-std-workspace-std" { needs_rustc_std = true ; } } } } } if needs_rustc_alloc || needs_rustc_core || needs_rustc_std { let deps = doc . entry ("dependencies") . or_insert (toml_edit :: Item :: Table (toml_edit :: Table :: new ())) ; let deps_table = deps . as_table_mut () . unwrap () ; if needs_rustc_alloc && ! deps_table . contains_key ("rustc-std-workspace-alloc") { deps_table . insert ("rustc-std-workspace-alloc" , value ("1.0.0")) ; } if needs_rustc_core && ! deps_table . contains_key ("rustc-std-workspace-core") { deps_table . insert ("rustc-std-workspace-core" , value ("1.0.0")) ; } if needs_rustc_std && ! deps_table . contains_key ("rustc-std-workspace-std") { deps_table . insert ("rustc-std-workspace-std" , value ("1.0.0")) ; } } } let has_dependencies = doc . get ("dependencies") . and_then (| d | d . as_table ()) . is_some () ; if let Some (features) = doc . get_mut ("features") . and_then (| f | f . as_table_mut ()) { let mut features_to_fix = Vec :: new () ; for (feature_name , feature_list) in features . iter () { if let Some (arr) = feature_list . as_array () { let mut new_deps = Vec :: new () ; let mut changed = false ; for item in arr . iter () { if let Some (s) = item . as_str () { if s . starts_with ("rustc-std-workspace-") { if has_dependencies { new_deps . push (s . to_string ()) ; } else { changed = true ; println ! ("⚠️  Removing unresolvable feature dependency: {} from feature {}" , s , feature_name) ; } } else { new_deps . push (s . to_string ()) ; } } } if changed { features_to_fix . push ((feature_name . to_string () , new_deps)) ; } } } for (feature_name , new_deps) in features_to_fix { let new_array = toml_edit :: Array :: from_iter (new_deps . into_iter () . map (| s | toml_edit :: Value :: from (s))) ; features . insert (& feature_name , toml_edit :: Item :: Value (toml_edit :: Value :: Array (new_array))) ; } } std :: fs :: write (cargo_toml_path , doc . to_string ()) ? ; Ok (()) }
}